import{_ as s,a0 as o,w as i,s as l,ao as r,I as p,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu","title":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu.md","filePath":"[post].md"}'),g={name:"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu.md"};function b(d,t,T,m,U,C){const u=o("Link");return i(),l("div",null,[t[11]||(t[11]=r('<h1 id="每日-ubuntu-小技巧-更改-ubuntu-使用語言" tabindex="-1">每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言 <a class="header-anchor" href="#每日-ubuntu-小技巧-更改-ubuntu-使用語言" aria-label="Permalink to “每日 Ubuntu 小技巧 - 更改 Ubuntu 使用語言”">​</a></h1><p>Ubuntu 是一個功能強大的現代化操作系統，並且它還允許你使用多種語言的桌面。在默認情況下，在你第一次安裝 Ubuntu 的時候會預裝幾個語言包。但如果你想要你的 Ubuntu 能夠支持更多語言的話，那你就必須安裝額外的語言包。通常不是所有的語言都是支持的，但是大多數使用中的語言以及書面語言都能夠被支持。下面是一個是簡短教程，它將會展示如何去實現。</p><p>在安裝語言包之後，你可以根據你的語言重命名標準文件夾，例如音樂、圖片和文檔。你必須註銷系統然後重新登錄來使變更生效。當你重新登錄之後，你會看到一個彈窗並且詢問你是否願意重命名這些標準文件夾，從而使得文件名滿足你的所選擇的語言要求。</p><p>要想更改 Ubuntu 的使用語言，單擊菜單欄右上角的 <strong>齒輪</strong>，並且選擇 <strong>System Settings（系統設置）</strong>。在打開 System Settings（系統設置） 之後，選擇 <strong>Language Support（語言支持）</strong>。</p><p>如果提示要你安裝額外的語言支持，那就直接安裝。如果沒有，那麼就單擊 Install / Remove （安裝/刪除）去安裝新的語言包，然後，選擇你想安裝的語言來安裝。最後，拖動新的語言到列表的頂端並且保存。這些更改只會應用在你的個人帳號上。如果你想應用在全局範圍內，單擊 <strong>Apply System-Wide（應用到全局設置）</strong> 。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu.png" alt=""></p><p>拖動新的語言到列表的頂端。之後單擊 Close。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu-1.png" alt=""></p><p>關閉之後註銷系統。然後重新登錄，你就會看到更改生效了。</p><p>同樣，語言包的更改只是應用在你的個人帳號上。如果你想全局更改的話，你必須單擊 Apply System-Wide。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu-2.png" alt=""></p><p>如果你選擇了重命名標準文件夾，你必須重新登錄才能看到變更。</p><p>好好享受吧！</p><hr>',14)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tipschange-the-language-you-use-in-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/10/daily-ubuntu-tipschange-the-language-you-use-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("譯者：",-1)),e(u,{href:"https://github.com/hyaocuk"},{default:a(()=>[...t[2]||(t[2]=[n("hyaocuk",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),e(u,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),e(u,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const y=s(g,[["render",b]]);export{h as __pageData,y as default};
